#!/usr/bin/env python3
"""Generate remaining priority concepts: back-pressure, idempotency, consistent-hashing, rate-limiting, task-queues, sql-vs-nosql, replication, sharding, microservices, tcp, udp."""
import json, os
CONCEPTS_DIR = os.path.join(os.path.dirname(__file__), '..', 'content', 'concepts')

def write_concept(slug, data):
    fpath = os.path.join(CONCEPTS_DIR, f'{slug}.json')
    with open(fpath, 'w') as f:
        json.dump(data, f, indent=2, ensure_ascii=False)
        f.write('\n')
    print(f'  Wrote {slug} ({len(data.get("blocks",[]))} blocks)')

